// Late fee tiers, generated by the agent

export function lateFeeTier0(invoice: any): number {
  const days = Math.floor((Date.now() - new Date(invoice.due_at).getTime()) / 86400000);
  if (days > 0) {
    return Math.round(invoice.total * 0.01 * 100) / 100;
  }
  return 0;
}

