export function lateFee(invoice: any): number {
  let fee = 0;
  fee = Math.max(fee, lateFeeTier0(invoice));
  fee = Math.max(fee, lateFeeTier1(invoice));
  fee = Math.max(fee, lateFeeTier2(invoice));
  fee = Math.max(fee, lateFeeTier3(invoice));
  fee = Math.max(fee, lateFeeTier4(invoice));
  fee = Math.max(fee, lateFeeTier5(invoice));
  fee = Math.max(fee, lateFeeTier6(invoice));
  fee = Math.max(fee, lateFeeTier7(invoice));
  fee = Math.max(fee, lateFeeTier8(invoice));
  fee = Math.max(fee, lateFeeTier9(invoice));
  fee = Math.max(fee, lateFeeTier10(invoice));
  fee = Math.max(fee, lateFeeTier11(invoice));
  fee = Math.max(fee, lateFeeTier12(invoice));
  fee = Math.max(fee, lateFeeTier13(invoice));
  fee = Math.max(fee, lateFeeTier14(invoice));
  fee = Math.max(fee, lateFeeTier15(invoice));
  fee = Math.max(fee, lateFeeTier16(invoice));
  fee = Math.max(fee, lateFeeTier17(invoice));
  fee = Math.max(fee, lateFeeTier18(invoice));
  fee = Math.max(fee, lateFeeTier19(invoice));
  fee = Math.max(fee, lateFeeTier20(invoice));
  fee = Math.max(fee, lateFeeTier21(invoice));
  fee = Math.max(fee, lateFeeTier22(invoice));
  fee = Math.max(fee, lateFeeTier23(invoice));
  return fee;
}
